contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 claimAmount) public payable {
        require(claimAmount > 0, "claim amount must be positive");

        address thisAddr = address(this);

        // Give this test contract some sGLP and USDC and set up the vault as the caller of depositToken.
        // Use the public getter for dnGmxJuniorVault to know which address must be impersonated for depositToken.
        // However, we cannot call as another address. Instead, we only test executeBatchDeposit as the keeper.
        // We call the public getters to read observable state.

        uint256 glpBalBefore = c.dnGmxJuniorVaultGlpBalance();
        uint256 roundBefore = c.currentRound();
        uint256 roundGlpBefore = c.roundGlpStaked();

        // The test contract must be the keeper. Since c is deployed by this test, we can call setKeeper.
        // This is a state-changing call and must be a top-level statement.
        c.setKeeper(address(this));

        // Cooldown requirement: executeBatchDeposit requires block.timestamp > lastUnpauseTimestamp + 15 minutes.
        // We cannot advance time. However, if the initial lastUnpauseTimestamp is 0 and block.timestamp is large,
        // the cooldown may already be satisfied. If not, the call will revert. We capture the revert.
        bool reverted;
        try c.executeBatchDeposit() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 glpBalAfter = c.dnGmxJuniorVaultGlpBalance();
        uint256 roundAfter = c.currentRound();

        // General rule: if executeBatchDeposit succeeds and the contract held GLP balance before the call,
        // then after the call the GLP balance is zero. Also, if the round GLP staked was zero before,
        // the current round must not have advanced.
        bool glpReset = (reverted || glpBalBefore == 0 || glpBalAfter == 0);
        bool roundNotAdvanced = (reverted || roundGlpBefore != 0 || roundAfter == roundBefore);
        assert(glpReset && roundNotAdvanced);
    }

    receive() external payable {}
}

