contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address receiver, address user) public payable {
        require(user != address(0) && receiver != address(0), "invalid addresses");
        require(amount > 0 && amount <= type(uint128).max, "invalid amount");

        uint256 beforeUnclaimed = c.unclaimedShares(user);

        bool reverted;
        try c.claim(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterUnclaimed = c.unclaimedShares(user);

        if (reverted) {
            assert(afterUnclaimed == beforeUnclaimed);
