    constructor(C _c) { c = _c; }

    function run(uint256 amount, address receiver) public payable {
        require(receiver != address(0), "zero receiver");
        require(amount > 0 && amount <= type(uint128).max, "amount out of range");

        c.depositUsdc(amount, receiver);

        assert(c.usdcBalance(receiver) == amount);
    }

    receive() external payable {}
}

