contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address receiver) public payable {
        require(amount > 0);
        require(receiver != address(0));
        require(amount <= type(uint128).max);

        uint256 roundBefore = c.currentRound();
        uint256 balanceBefore = c.usdcBalance(receiver);

        c.depositUsdc(amount, receiver);

        uint256 roundAfter = c.currentRound();
        uint256 balanceAfter = c.usdcBalance(receiver);

        assert(balanceAfter == balanceBefore + amount && roundAfter == roundBefore);
    }

    receive() external payable {}
}

